&reftitle.description;
public resourceStreamPollHandle::getStream
Returns the stream that was passed to StreamPollHandle::__construct.

  &reftitle.examples;

   StreamPollHandle::getStream example


<?php
[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$handle = new StreamPollHandle($reader);
var_dump($handle->getStream() === $reader);

fclose($reader);
var_dump(is_resource($handle->getStream()));


   &example.outputs;


bool(true)
bool(false)
